create or replace function public.fn_decide_approval(
  p_approval_id uuid,
  p_decision text,
  p_justification text default null
)
returns public.workflow_instances
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_approval public.approvals;
  v_instance_step public.workflow_instance_steps;
  v_step public.workflow_steps;
  v_instance public.workflow_instances;
  v_eligible boolean;
  v_received integer;
  v_next_step record;
  v_next_instance_step public.workflow_instance_steps;
  v_current_user uuid;
begin
  if p_decision not in ('APPROVED', 'REJECTED', 'RETURNED') then
    raise exception 'Decisão inválida: %.', p_decision using errcode = '22023';
  end if;

  select * into v_approval from public.approvals where id = p_approval_id;
  if not found then
    raise exception 'Aprovação não encontrada.' using errcode = 'P0002';
  end if;

  select * into v_instance_step from public.workflow_instance_steps where id = v_approval.workflow_instance_step_id for update;
  if not found then
    raise exception 'Etapa de instância não encontrada.' using errcode = 'P0002';
  end if;

  select * into v_approval from public.approvals where id = p_approval_id;
  if v_approval.status <> 'PENDING' then
    raise exception 'Esta aprovação já foi decidida ou cancelada.' using errcode = 'P0001';
  end if;

  if v_instance_step.status <> 'IN_PROGRESS' then
    raise exception 'Esta etapa não está aguardando decisão (status atual: %).', v_instance_step.status using errcode = 'P0001';
  end if;

  select * into v_step from public.workflow_steps where id = v_instance_step.workflow_step_id;
  select * into v_instance from public.workflow_instances where id = v_instance_step.workflow_instance_id;

  if not public.has_permission(v_instance.company_id, case when p_decision = 'REJECTED' then 'workflow.reject' else 'workflow.approve' end) then
    raise exception 'Permissão negada (%).', case when p_decision = 'REJECTED' then 'workflow.reject' else 'workflow.approve' end using errcode = '42501';
  end if;

  v_current_user := public.current_app_user_id();
  if v_approval.approver_type = 'USER' then
    v_eligible := v_approval.user_id = v_current_user;
  else
    v_eligible := exists (
      select 1 from public.user_roles ur
      where ur.user_id = v_current_user and ur.role_id = v_approval.role_id
    );
  end if;

  if not v_eligible then
    raise exception 'Você não é um aprovador elegível para esta etapa.' using errcode = '42501';
  end if;

  if p_decision = 'REJECTED' and v_step.require_justification_on_reject and coalesce(trim(p_justification), '') = '' then
    raise exception 'Justificativa obrigatória para rejeitar esta etapa.' using errcode = 'P0001';
  end if;

  insert into public.approval_decisions (company_id, approval_id, workflow_instance_step_id, decided_by, decision, justification)
  values (v_instance.company_id, p_approval_id, v_instance_step.id, v_current_user, p_decision, p_justification);

  update public.approvals set status = 'DECIDED' where id = p_approval_id;

  insert into public.approval_history (company_id, workflow_instance_id, workflow_instance_step_id, event_type, actor_user_id, message)
  values (v_instance.company_id, v_instance.id, v_instance_step.id, p_decision, v_current_user,
    coalesce(p_justification, format('Decisão: %s.', p_decision)));

  if p_decision = 'REJECTED' then
    update public.workflow_instance_steps set status = 'REJECTED', finished_at = now() where id = v_instance_step.id;
    update public.workflow_instances set status = 'REJECTED', finished_at = now() where id = v_instance.id returning * into v_instance;
    insert into public.approval_history (company_id, workflow_instance_id, event_type, actor_user_id, message)
    values (v_instance.company_id, v_instance.id, 'FINISHED', v_current_user, 'Workflow finalizado: rejeitado.');
    return v_instance;
  end if;

  if p_decision = 'RETURNED' then
    update public.workflow_instance_steps set status = 'RETURNED', finished_at = now() where id = v_instance_step.id;
    update public.workflow_instances set status = 'RETURNED', finished_at = now() where id = v_instance.id returning * into v_instance;
    insert into public.approval_history (company_id, workflow_instance_id, event_type, actor_user_id, message)
    values (v_instance.company_id, v_instance.id, 'FINISHED', v_current_user, 'Workflow finalizado: retornado para correção.');
    return v_instance;
  end if;

  select count(*) into v_received from public.approval_decisions
  where workflow_instance_step_id = v_instance_step.id and decision = 'APPROVED';

  update public.workflow_instance_steps set received_approvals = v_received where id = v_instance_step.id;

  if v_received < v_instance_step.required_approvals then
    return v_instance;
  end if;

  update public.workflow_instance_steps set status = 'APPROVED', finished_at = now() where id = v_instance_step.id;

  select ws.* into v_next_step from public.workflow_steps ws
  join public.workflow_instance_steps wis on wis.workflow_step_id = ws.id and wis.workflow_instance_id = v_instance.id
  where wis.step_order > v_instance_step.step_order and wis.status = 'PENDING'
  order by wis.step_order
  limit 1;

  if found then
    select wis.* into v_next_instance_step from public.workflow_instance_steps wis
    where wis.workflow_instance_id = v_instance.id and wis.workflow_step_id = v_next_step.id;

    update public.workflow_instance_steps
    set status = 'IN_PROGRESS', started_at = now(),
        due_at = case when v_next_step.sla_hours is not null then now() + make_interval(hours => v_next_step.sla_hours) else null end
    where id = v_next_instance_step.id;

    insert into public.approvals (company_id, workflow_instance_step_id, approver_type, user_id, role_id)
    select v_instance.company_id, v_next_instance_step.id, wsa.approver_type, wsa.user_id, wsa.role_id
    from public.workflow_step_approvers wsa
    where wsa.workflow_step_id = v_next_step.id;

    update public.workflow_instances set current_step_id = v_next_instance_step.id where id = v_instance.id returning * into v_instance;

    insert into public.approval_history (company_id, workflow_instance_id, workflow_instance_step_id, event_type, actor_user_id, message)
    values (v_instance.company_id, v_instance.id, v_next_instance_step.id, 'STEP_ADVANCED', v_current_user,
      format('Avançou para a etapa "%s".', v_next_step.name));
  else
    update public.workflow_instances set status = 'APPROVED', finished_at = now() where id = v_instance.id returning * into v_instance;
    insert into public.approval_history (company_id, workflow_instance_id, event_type, actor_user_id, message)
    values (v_instance.company_id, v_instance.id, 'FINISHED', v_current_user, 'Workflow finalizado: aprovado.');
  end if;

  return v_instance;
end;
$$;

create or replace function public.fn_upsert_setting(
  p_company_id uuid,
  p_establishment_id uuid,
  p_module text,
  p_key text,
  p_value_type text,
  p_value_string text default null,
  p_value_integer bigint default null,
  p_value_decimal numeric default null,
  p_value_boolean boolean default null,
  p_value_date date default null,
  p_value_json jsonb default null,
  p_description text default null,
  p_valid_from date default null,
  p_valid_until date default null
)
returns public.system_settings
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_existing public.system_settings;
  v_setting public.system_settings;
  v_scope_key uuid;
  v_check_company_id uuid;
begin
  select id into v_existing
  from public.system_settings
  where module = p_module and key = p_key
    and coalesce(company_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(p_company_id, '00000000-0000-0000-0000-000000000000'::uuid)
    and coalesce(establishment_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(p_establishment_id, '00000000-0000-0000-0000-000000000000'::uuid);

  if p_establishment_id is not null then
    if p_company_id is null then
      raise exception 'Configuração de estabelecimento exige company_id.' using errcode = '22023';
    end if;
    v_check_company_id := p_company_id;
    if not public.has_permission(v_check_company_id, 'settings.establishment.update') then
      raise exception 'Permissão negada (settings.establishment.update).' using errcode = '42501';
    end if;
  elsif p_company_id is not null then
    v_check_company_id := p_company_id;
    if not public.has_permission(v_check_company_id, 'settings.company.update') then
      raise exception 'Permissão negada (settings.company.update).' using errcode = '42501';
    end if;
  else
    v_check_company_id := coalesce(p_company_id, (select company_id from public.users where id = public.current_app_user_id()));
    if v_existing is null then
      if not public.has_permission(v_check_company_id, 'settings.create') then
        raise exception 'Permissão negada (settings.create).' using errcode = '42501';
      end if;
    else
      if not public.has_permission(v_check_company_id, 'settings.update') then
        raise exception 'Permissão negada (settings.update).' using errcode = '42501';
      end if;
    end if;
  end if;

  insert into public.system_settings (
    company_id, establishment_id, module, key, value_type,
    value_string, value_integer, value_decimal, value_boolean, value_date, value_json,
    description, valid_from, valid_until, created_by
  ) values (
    p_company_id, p_establishment_id, p_module, p_key, p_value_type,
    p_value_string, p_value_integer, p_value_decimal, p_value_boolean, p_value_date, p_value_json,
    p_description, p_valid_from, p_valid_until, public.current_app_user_id()
  )
  on conflict (module, key, (coalesce(company_id, '00000000-0000-0000-0000-000000000000'::uuid)), (coalesce(establishment_id, '00000000-0000-0000-0000-000000000000'::uuid)))
  do update set
    value_type = excluded.value_type, value_string = excluded.value_string, value_integer = excluded.value_integer,
    value_decimal = excluded.value_decimal, value_boolean = excluded.value_boolean, value_date = excluded.value_date,
    value_json = excluded.value_json, description = coalesce(excluded.description, public.system_settings.description),
    valid_from = excluded.valid_from, valid_until = excluded.valid_until
  returning * into v_setting;

  insert into public.audit_logs (company_id, user_id, actor_label, entity, entity_id, action, old_data, new_data)
  values (p_company_id, public.current_app_user_id(), 'system', 'system_settings', v_setting.id,
    case when v_existing is null then 'CREATE' else 'UPDATE' end,
    case when v_existing is not null then jsonb_build_object('module', p_module, 'key', p_key) else null end,
    jsonb_build_object('module', p_module, 'key', p_key, 'value_type', p_value_type));

  return v_setting;
end;
$$;

create table if not exists public.platform_role_permissions (
  platform_role text not null check (platform_role in ('OWNER', 'ADMIN')),
  permission_code text not null references public.platform_permissions(code) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (platform_role, permission_code)
);

-- ==================================================================
-- fn_upsert_platform_member — único caminho de escrita.
-- Regras: ADMIN administra ADMIN; apenas OWNER cria/altera/rebaixa
-- OWNER; nunca é possível remover o último OWNER ativo.
-- ==================================================================
create or replace function public.fn_upsert_platform_member(
  p_auth_user_id uuid,
  p_name text,
  p_email text,
  p_platform_role text,
  p_status text default 'active'
)
returns public.platform_members
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_existing public.platform_members;
  v_member public.platform_members;
  v_owner_count integer;
begin
  if p_platform_role not in ('OWNER', 'ADMIN') then
    raise exception 'platform_role inválido: % (use OWNER ou ADMIN).', p_platform_role using errcode = '22023';
  end if;
  if p_status not in ('active', 'inactive') then
    raise exception 'status inválido: %.', p_status using errcode = '22023';
  end if;

  if not public.has_platform_permission('platform.members.manage') then
    raise exception 'Permissão negada (platform.members.manage).' using errcode = '42501';
  end if;

  select * into v_existing from public.platform_members where auth_user_id = p_auth_user_id;

  if (p_platform_role = 'OWNER' or coalesce(v_existing.platform_role, '') = 'OWNER')
     and not public.is_platform_owner() then
    raise exception 'Apenas o Platform Owner pode criar ou alterar outro Owner.' using errcode = '42501';
  end if;

  if v_existing.id is not null and v_existing.platform_role = 'OWNER'
     and (p_platform_role <> 'OWNER' or p_status <> 'active') then
    select count(*) into v_owner_count
    from public.platform_members
    where platform_role = 'OWNER' and status = 'active' and id <> v_existing.id;
    if v_owner_count = 0 then
      raise exception 'Não é possível remover/rebaixar o último Platform Owner ativo.' using errcode = 'P0001';
    end if;
  end if;

  insert into public.platform_members (auth_user_id, name, email, platform_role, status, created_by)
  values (p_auth_user_id, p_name, p_email, p_platform_role, p_status, public.current_platform_member_id())
  on conflict (auth_user_id) do update
    set name = excluded.name,
        email = excluded.email,
        platform_role = excluded.platform_role,
        status = excluded.status
  returning * into v_member;

  perform public.fn_log_platform_audit(
    'platform_members', v_member.id,
    case when v_existing.id is null then 'CREATE' else 'UPDATE' end,
    case when v_existing.id is null then null else jsonb_build_object('platform_role', v_existing.platform_role, 'status', v_existing.status) end,
    jsonb_build_object('platform_role', v_member.platform_role, 'status', v_member.status, 'email', v_member.email)
  );

  return v_member;
end;
$$;

-- ==================================================================
-- bootstrap_platform_owner — criação do PRIMEIRO owner, só enquanto
-- não existir nenhum owner ativo. Mesmo padrão (e mesma limitação
-- proposital) de bootstrap_admin_user: exposto apenas a service_role,
-- nunca a authenticated.
-- ==================================================================
create or replace function public.bootstrap_platform_owner(
  p_auth_user_id uuid,
  p_name text,
  p_email text
)
returns public.platform_members
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_owner_count integer;
  v_member public.platform_members;
begin
  select count(*) into v_owner_count
  from public.platform_members where platform_role = 'OWNER' and status = 'active';

  if v_owner_count > 0 then
    raise exception 'Já existe um Platform Owner ativo. Use fn_upsert_platform_member.' using errcode = 'P0001';
  end if;

  insert into public.platform_members (auth_user_id, name, email, platform_role, status)
  values (p_auth_user_id, p_name, p_email, 'OWNER', 'active')
  on conflict (auth_user_id) do update
    set platform_role = 'OWNER', status = 'active', name = excluded.name, email = excluded.email
  returning * into v_member;

  perform public.fn_log_platform_audit('platform_members', v_member.id, 'CREATE', null,
    jsonb_build_object('platform_role', 'OWNER', 'email', p_email, 'bootstrap', true));

  return v_member;
end;
$$;

